Whatever-First Search
def whatever_first_search(start, neighbors):
    bag = Bag([start])
    visited = {start}

    while bag:
        current = bag.get()
        for neighbor in neighbors(current):
            if neighbor not in visited:
                visited.add(neighbor)
                bag.put(neighbor)

    return visited
