def binary_search(arr, target, lo, hi):
    if lo &gt; hi:
        return -1
    mid = (lo + hi) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] &lt; target:
        return binary_search(arr, target, mid+1, hi)  
    else:
